            <div aria-hidden="true" className="art:absolute art:right-10 art:bottom-10 art:size-40 art:rounded-full art:border art:border-border/60"/>
            <div className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:p-5 art:@min-[640px]/artemis:p-8">
