            const offset = index - active;
            const isActive = offset === 0;
            return (<motion.button key={story.label} type="button" className={CARD_CLASS} aria-pressed={isActive} tabIndex={0} style={{ zIndex: isActive ? 30 : 20 - Math.abs(offset) }} initial={{ opacity: 0, x: "0%", y: 48, scale: 1, rotate: 8 * index }} animate={reduce ? { opacity: isActive ? 1 : 0.68 } : placement(offset)} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT} onClick={() => setActive(index)}>
